# Reference-reproduction adjustment block. The square photographed artwork is
# fitted uniformly to A5. Its complete width is retained and centered vertically;
# the small app watermark in the lower-right corner remains part of the reference.
CANVAS_SIZE = (148, 210)
BACKGROUND_COLOR = (1.0, 1.0, 1.0)
LINE_THICKNESS = 0.001
SEED = 8122026
PALETTE_RGB = [(0, 0, 0), (23, 21, 20), (44, 29, 19), (80, 55, 36), (109, 83, 62), (117, 93, 70), (140, 100, 61), (180, 128, 84), (183, 135, 79), (205, 168, 121), (185, 135, 79), (185, 126, 88), (236, 117, 61), (96, 207, 250), (82, 155, 180), (143, 180, 192), (179, 192, 195), (197, 211, 211), (156, 149, 145), (171, 171, 168), (220, 217, 210), (237, 238, 235), (217, 205, 191), (255, 255, 255)]
LINE_COLORS = {color_name: tuple(channel / 255.0 for channel in rgb) for color_name, rgb in zip(
    ("black", "umber", "blue_black", "charcoal", "rust", "deep_blue", "olive_brown", "brown", "terracotta", "slate", "taupe", "steel", "orange", "cyan_blue", "ochre", "khaki", "blue_gray", "sky_blue", "sand", "electric_cyan", "gold", "pale_cyan", "paper_shadow", "white"),
    PALETTE_RGB,
)}
# No area-fill effect is used: each source-pixel cell is represented directly by
# dense plotter scanlines. These constants control that complete fill treatment.
FILL_DENSITIES = {"raster_scan": 1000.0}
FILL_MIN_SPACINGS = {"raster_scan": 0.032}
REFERENCE_SIZE = (1179.0, 1149.0)
LAYOUT_FIT_SCALE = min(CANVAS_SIZE[0] / REFERENCE_SIZE[0], CANVAS_SIZE[1] / REFERENCE_SIZE[1])
LAYOUT_CROP = (0.0, 0.0, 0.0, 0.0)
RASTER_WIDTH = 512
RASTER_HEIGHT = 499
LAYOUT_SCALE = CANVAS_SIZE[0] / RASTER_WIDTH
LAYOUT_OFFSET = (0.0, (CANVAS_SIZE[1] - RASTER_HEIGHT * LAYOUT_SCALE) / 2.0)
RASTER_SCAN_SPACING = min(
    max(FILL_MIN_SPACINGS["raster_scan"], 100.0 / FILL_DENSITIES["raster_scan"]),
    LINE_THICKNESS * min(CANVAS_SIZE) / 6.0,
)

