def _pack(polylines: list[list[tuple[float, float]]]) -> tuple[np.ndarray, np.ndarray]:
    values: list[tuple[float, float, float]] = []
    offsets = [0]
    for polyline in polylines:
        if len(polyline) < 2:
            continue
        values.extend((float(x), float(y), 0.0) for x, y in polyline)
        offsets.append(len(values))
    coords = np.asarray(values, dtype=np.float32).reshape((-1, 3))
    indices = np.asarray(offsets, dtype=np.int32)
    return np.ascontiguousarray(coords), np.ascontiguousarray(indices)


@lru_cache(maxsize=1)
def _index_image() -> np.ndarray:
    raw = zlib.decompress(base64.b85decode(_RASTER_B85.encode("ascii")))
    return np.frombuffer(raw, dtype=np.uint8).reshape((RASTER_HEIGHT, RASTER_WIDTH))


def _layer_data(palette_index: int) -> tuple[np.ndarray, np.ndarray]:
    indices = _index_image()
    polylines: list[list[tuple[float, float]]] = []
    cell = LAYOUT_SCALE
    x_offset, y_offset = LAYOUT_OFFSET
    # Several sub-scanlines per quantized row make every indexed source cell an
    # opaque-looking plotted colour patch at the fixed 0.001 layer thickness.
    subline_count = max(2, int(np.ceil(cell / RASTER_SCAN_SPACING)))
    for row in range(RASTER_HEIGHT):
        mask = indices[row] == palette_index
        if not bool(mask.any()):
            continue
        padded = np.pad(mask.astype(np.int8), (1, 1))
        changes = np.flatnonzero(np.diff(padded))
        source_y0 = y_offset + row * cell
        for start, end in changes.reshape((-1, 2)):
            x0 = x_offset + float(start) * cell
            x1 = x_offset + float(end) * cell
            for subline in range(subline_count):
                y = source_y0 + (subline + 0.5) * cell / subline_count
                # Alternate direction to preserve efficient boustrophedon flow.
                polylines.append([(x0, y), (x1, y)] if subline % 2 == 0 else [(x1, y), (x0, y)])
    return _pack(polylines)


@primitive
def indexed_scan_layer(*, palette_index: int = 0) -> tuple[np.ndarray, np.ndarray]:
    """Return dense horizontal plotter strokes for one indexed source colour."""

    coords, offsets = _layer_data(int(palette_index))
    return coords.copy(), offsets.copy()


def draw(t: float):
    del t
    layers = []
    for index, (color_name, color) in enumerate(LINE_COLORS.items()):
        geometry = G(name=f"Indexed source colour / {color_name}").indexed_scan_layer(
            palette_index=index,
            key="look-alive-indexed-scan-layer",
            instance_key=f"{index:02d}-{color_name}",
        )
        layers.append(
            L(name=f"Look Alive / {color_name}").layer(
                geometry,
                color=color,
                thickness=LINE_THICKNESS,
            )
        )
    return tuple(layers)


if __name__ == "__main__":
    run(
        draw,
        canvas_size=CANVAS_SIZE,
        render_scale=4.0,
        background_color=BACKGROUND_COLOR,
        line_color=LINE_COLORS["black"],
        line_thickness=LINE_THICKNESS,
        parameter_persistence=False,
        midi_port_name=None,
        n_worker=0,
        seed=SEED,
    )
